BEGIN TRANSACTION READ ONLY; SET LOCAL search_path=pg_catalog,public;
SELECT jsonb_build_object(
'captured_at',now(),
'auth_uid',(SELECT pg_get_functiondef('auth.uid()'::regprocedure)),
'signup_triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid='auth.users'::regclass AND p.proname='hka_signup_profile' AND NOT t.tgisinternal),
'required_tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('hka_messages','hka_profiles','hka_account_roles','hka_guardians','hka_coach_students','hka_link_requests','hka_student_link_codes')),
'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypass_rls',rolbypassrls,'can_login',rolcanlogin)) FROM pg_roles WHERE rolname IN ('postgres','anon','authenticated','service_role')),
'graphql_schemas',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'functions',(SELECT count(*) FROM pg_proc p WHERE p.pronamespace=n.oid))) FROM pg_namespace n WHERE n.nspname IN ('graphql','graphql_public'))
) AS snapshot; COMMIT;
